const ctx = $('▶️ 03 Generador IA').first().json;
const d = ctx.datosRecolectados || {};

// Only show price if all data collected and not already sent
// Use proximoPaso from 01 Clasificador as source of truth — includes all checks (correo, proteccion, etc.)
if (!ctx.todosRecolectados || ctx.cotizacionEnviada) {
  return [{ json: { ...ctx } }];
}

// Read precio from HTTP node result
const apiResp = $input.first().json;
const precio = apiResp?.data?.precio_total || apiResp?.precio_total || null;

const idioma = ctx.idiomaConversacion || 'español';
const nombre = d.nombre_cliente ? `, ${d.nombre_cliente.split(' ')[0]}` : '';
const medTxt = d.medidas ? (/(in|")\s*$/i.test(String(d.medidas).trim()) ? d.medidas : d.medidas + '"') : '—';
const tieneProteccion = d.proteccion_extra === true || d.proteccion_extra === 'true';
// Cantidad y precio legible (17-nov): el cotizador puede devolver decimales largos (165.60000000000002)
const cant = Math.min(500, Math.max(1, parseInt(d.cantidad, 10) || 1));
const precioTxt = precio ? Number(precio).toLocaleString('en-US', { minimumFractionDigits: Number(precio) % 1 ? 2 : 0, maximumFractionDigits: 2 }) : null;
const cantEs = d.cantidad ? `\n🔢 Cantidad: ${cant}` : '';
const cantEn = d.cantidad ? `\n🔢 Quantity: ${cant}` : '';
const notaEs = d.cantidad ? (cant > 1 ? ` (${cant} unidades)` : '') : ' (por 1 unidad; si necesitas varias, dime cuántas)';
const notaEn = d.cantidad ? (cant > 1 ? ` (${cant} units)` : '') : ' (for 1 unit; if you need more, tell me how many)';
// Descuento por volumen (17-nov, decisión de la usuaria): desde 2 unidades el descuento lo decide un vendedor.
// Marco da el precio de lista, avisa que un vendedor confirma el precio final y el caso pasa como lead caliente.
const descuentoVolumen = !!precio && cant >= 2;
const lineaDescEs = descuentoVolumen ? `\n🏷 Por ser ${cant} unidades aplica descuento por volumen: un vendedor revisa tu caso y te confirma el precio final.` : '';
const lineaDescEn = descuentoVolumen ? `\n🏷 Since it's ${cant} units, a volume discount applies: a sales rep will review your case and confirm the final price.` : '';

let mensajeFinal;
if (precio) {
  if (idioma === 'inglés') {
    mensajeFinal = `Here is your estimate${nombre}! 🎉\n\n📦 *${d.producto || 'Crate'}*\n📐 Dimensions: ${medTxt}\n🗓 Needed by: ${d.fecha || '—'}\n🛡 Extra protection: ${tieneProteccion ? 'Yes' : 'No'}${cantEn}\n\n💵 *${descuentoVolumen ? 'List price' : 'Estimated price'}: $${precioTxt} USD*${notaEn}${lineaDescEn}\n_This is an estimate. The final price may vary after inspection._\n\nWould you like a formal quote sent to your email?`;
  } else {
    mensajeFinal = `¡Aquí está tu estimado${nombre}! 🎉\n\n📦 *${d.producto || 'Cajón'}*\n📐 Medidas: ${medTxt}\n🗓 Para: ${d.fecha || '—'}\n🛡 Protección extra: ${tieneProteccion ? 'Sí' : 'No'}${cantEs}\n\n💵 *${descuentoVolumen ? 'Precio de lista' : 'Precio estimado'}: $${precioTxt} USD*${notaEs}${lineaDescEs}\n_Este es un estimado. El precio final puede variar luego de la inspección._\n\n¿Quieres que te enviemos la cotización formal a tu correo?`;
  }
} else {
  mensajeFinal = ctx.mensaje;
}

return [{ json: {
  ...ctx,
  mensaje: mensajeFinal,
  mensajeRespuesta: mensajeFinal,
  descuentoVolumen,
  cantidadPedida: cant,
  ...(descuentoVolumen ? { clasificacion: 'Caliente' } : {}),
  cotizadorEnviado: !!precio
} }];

const armar = $('📝 Armar Mensaje Final').first().json;
const tradResp = $input.first().json;
// Extract translated text from Groq response
const traducido = tradResp.choices?.[0]?.message?.content?.replace(/<\/?mensaje>/gi, '').trim();
const mensajeFinal = traducido || armar.mensajeRespuesta || armar.mensaje || '';
return [{ json: { ...armar, mensaje: mensajeFinal, mensajeRespuesta: mensajeFinal } }];
// 18-nov: el texto va entre <mensaje> para que el traductor no lo responda; se quitan las etiquetas si las devuelve.

