const staticData = $getWorkflowStaticData('global');
const body = $json.body || $json;
const chatId = body.chat_id;
let texto = (body.texto || '').trim();

// Código de origen de una publicación (Content AI lo pone en cada post: "P" + id de la idea,
// ej. "Hola P456"). Se saca del texto que lee la IA y se guarda aparte para anotarlo en el CRM.
let origenPost = null;
{
  const mO = String(texto || '').match(/(?:^|[\s\[(])P-?(\d{2,7})(?=$|[\s\])\.,!?])/i);
  if (mO) {
    origenPost = Number(mO[1]);
    texto = String(texto).replace(/[\[(]?\bP-?\d{2,7}\b[\])]?[,.:;]?/i, ' ').replace(/\s+/g, ' ').replace(/^\s*[,.:;]\s*/, '').trim() || 'Hola';
  }
}
const conversationId = body.conversation_id;
const contactId = body.contact_id;
const nombreContacto = body.nombre || '';
const empresaId = body.empresa_id;

// Adjuntos (G54, 29-sep): fotos, notas de voz, audio y documentos llegan con
// file_id + tipo_adjunto (+ mime_type en voice/audio/document). `texto` es el pie, si vino.
const fileId = body.file_id || null;
const tipoAdjunto = body.tipo_adjunto || null;
let tipoMensaje = 'text', mimeType = null;
if (fileId) {
  if (tipoAdjunto === 'photo') { tipoMensaje = 'image'; mimeType = 'image/jpeg'; }
  else if (tipoAdjunto === 'voice') { tipoMensaje = 'audio'; mimeType = body.mime_type || 'audio/ogg'; }
  else if (tipoAdjunto === 'audio') { tipoMensaje = 'audio'; mimeType = body.mime_type || 'audio/mpeg'; }
  else { mimeType = body.mime_type || 'application/octet-stream'; tipoMensaje = mimeType === 'application/pdf' ? 'pdf' : 'document'; }
}

if (!chatId || (!texto && !fileId)) {
  return [{ json: { skip: true, skipReason: 'sin_chat_id_ni_contenido' } }];
}

// Deduplicación — G54 no manda un ID único de mensaje en el relevo, se arma con chat+conversación+contenido+ventana de tiempo
if (!staticData.seenTgMessageIds) staticData.seenTgMessageIds = {};
const now = Date.now();
Object.keys(staticData.seenTgMessageIds).forEach(id => {
  if (now - staticData.seenTgMessageIds[id] > 60000) delete staticData.seenTgMessageIds[id];
});
const dedupeKey = `${chatId}_${conversationId}_${fileId || ''}_${texto}`;
if (staticData.seenTgMessageIds[dedupeKey]) {
  return [{ json: { skip: true, skipReason: 'duplicate_message' } }];
}
staticData.seenTgMessageIds[dedupeKey] = now;

return [{
  json: {
    telefono: 'tg_' + chatId,
    chatId,
    texto,
    nombreContacto,
    conversationId,
    contactId,
    empresaId,
    tipoMensaje,
    fileId,
    mimeType,
    origenPost,
    skip: false
  }
}];

const dealResp = $json.deal || {};
const dealId = dealResp.id || null;

const partes = [];
try {
  const origenPost = $('🔧 Extraer Mensaje (Relevo G54)').first().json.origenPost;
  if (origenPost) partes.push('Origen: llegó desde la publicación P' + origenPost + ' (idea ' + origenPost + ').');
} catch (e) { /* sin código de origen */ }
let contenido = null;
try {
  const armado = $('📝 Armar Mensaje Final').item.json;
  const clasificacion = armado.clasificacion || '';
  if (clasificacion === 'Caliente') {
    contenido = 'Marco (Telegram): cliente acepto cotizacion, clasificado como lead caliente.';
  } else if (clasificacion === 'Consulta') {
    contenido = 'Marco (Telegram): consulta escalada a un especialista.';
  }
} catch (e) { /* si no se puede leer, no se loggea nada */ }

if (contenido) partes.push(contenido);
contenido = partes.length ? partes.join(' ') : null;
return [{ json: { dealId, contenido, deberiaLoggear: !!(dealId && contenido) } }];

