const armado = $('📝 Armar Mensaje Final').item.json;
const telefono = armado.telefono;

// Vinculo con el contacto de G54: primero el contact_id que manda el relevo de G54 (el dato
// mas directo), si no el lookup por telefono. G54 guarda el telefono con "+" (+tg_<chat>) y
// el lookup se hacia sin "+", asi que nunca encontraba nada y el trato quedaba sin vinculo
// (corregido 2026-09-30).
let wa_contact_id = null;
try { wa_contact_id = $('🔧 Extraer Mensaje (Relevo G54)').first().json.contactId || null; } catch (e) {}
if (!wa_contact_id) {
  try {
    const contactData = $('🔍 Buscar Contact ID (CRM Telegram)').item.json.data || [];
    wa_contact_id = contactData[0]?.id || null;
  } catch (e) { /* si fallo el lookup, seguimos sin el vinculo */ }
}

const temperatura = ({Caliente:'alto', Consulta:'medio'})[armado.clasificacion] || 'bajo';

// Origen de la publicación en el trato (08-oct): la etiqueta "origen:P<idea>" ya se guarda al crear
// el trato y se puede filtrar hoy; social_idea_id lo ignora G54 por ahora sin error y empieza a
// guardarse solo cuando exista la columna (pedido en el Éxodo). Solo se manda si vino el código,
// que llega en el primer mensaje: no pisa etiquetas de un trato ya existente en los demás turnos.
let origenCampos = {};
try { const op = $('🔧 Extraer Mensaje (Relevo G54)').first().json.origenPost; if (op) origenCampos = { tags: ['origen:P' + op], social_idea_id: Number(op) }; } catch (e) {}

return [{ json: {
  ...origenCampos,
  company_id: 1,
  telefono,
  nombre: armado.datosRecolectados?.nombre_cliente || telefono,
  origen: 'telegram', // antes 'whatsapp': el trato parecía de WhatsApp y el botón de seguimiento le mandaba WhatsApp (05-oct)
  wa_contact_id,
  temperatura,
  notas: 'Lead generado/actualizado por Marco (Telegram CE)',
}}];

// Reconstruye telefono/texto/nombreContacto desde el extractor real -- el nodo de bot-config (HTTP) que corre justo antes sobreescribe $json entero con la respuesta de la API, perdiendo estos campos. Mismo patron ya usado en el motor de WhatsApp (nodo "Preparar Contexto"), que Telegram nunca tuvo.
// Desde el 30-sep tambien pasa el adjunto (fileId/mimeType/tipoMensaje), si vino.
const ext = $('🔧 Extraer Mensaje (Relevo G54)').first().json;
return [{ json: { telefono: ext.telefono, texto: ext.texto, nombreContacto: ext.nombreContacto || '', fileId: ext.fileId || null, mimeType: ext.mimeType || null, tipoMensaje: ext.tipoMensaje || 'text' } }];

const c = $json;
return [{ json: {
  media_id: c.fileId,
  mime_type: c.mimeType,
  caption: c.texto || '',
  platform: 'telegram',
  phone_number_id: '',
  gemini_api_key: ''
} }];

// Convierte el adjunto en texto para Marco: transcripción del audio, descripción de la
// imagen o contenido del documento (06 Procesador de Medios). Si no se pudo abrir, Marco
// igual se entera de que llegó algo, en vez de no ver nada.
const r = $input.first().json || {};
const c = $('🔗 Preparar Contexto (TG)').first().json;
const etiquetas = { image: 'una imagen', audio: 'un audio', pdf: 'un documento PDF', document: 'un documento' };
const que = etiquetas[c.tipoMensaje] || 'un archivo';
const ok = r && !r.error && r.texto && !String(r.texto).startsWith('[Medio recibido pero no procesado');
let texto = ok ? `[Cliente envió ${que}] ${r.texto}` : `[Cliente envió ${que}, pero no se pudo abrir]`;
if (c.texto) texto += `\nMensaje del cliente: ${c.texto}`;
return [{ json: { telefono: c.telefono, texto, nombreContacto: c.nombreContacto, tipoMensaje: c.tipoMensaje } }];

const __httpConTope = (o) => this.helpers.httpRequest(Object.assign({ timeout: 120000 }, o)); // 17-nov: tope por defecto de 2 min si la llamada no trae uno
// 16-nov (revisión, punto 8): G54 reemplaza notas y temperatura en cada guardado del trato.
// El guardado anterior va sin esos dos campos; acá se completan solo si corresponde:
// - notas: solo si el trato es nuevo (no pisa lo que escribió el vendedor ni las marcas de Camila);
// - temperatura: solo si sube (un "gracias" después de aceptar no baja el trato de alto a bajo).
const pay = $('🔧 CRM: Preparar Payload (Telegram)').item.json;
const resp = $json;
const deal = resp && resp.deal;
if (!deal) return [{ json: resp }];
const rango = { bajo: 0, medio: 1, alto: 2 };
const extra = {};
if (resp.created && pay.notas) extra.notas = pay.notas;
if (pay.temperatura && (rango[pay.temperatura] ?? -1) > (rango[deal.temperatura] ?? -1)) extra.temperatura = pay.temperatura;
if (!Object.keys(extra).length) return [{ json: resp }];
const { notas, temperatura, ...base } = pay;
try {
  const r2 = await __httpConTope({
    method: 'POST',
    url: "https://apigrowth.mdarthurdigital.com/api/agent/crm/leads",
    headers: { Authorization: "Bearer REDACTED_G54_AGENT_TOKEN", 'Content-Type': 'application/json', Accept: 'application/json' },
    body: { ...base, ...extra }, json: true, timeout: 15000
  });
  return [{ json: r2 && r2.deal ? r2 : resp }];
} catch (e) {
  return [{ json: resp }];
}

const __httpConTope = (o) => this.helpers.httpRequest(Object.assign({ timeout: 120000 }, o)); // 17-nov: tope por defecto de 2 min si la llamada no trae uno
// 🔓 Sesiones G54 (17-nov): cada login maestro crea un token que no vence y n8n guarda la salida de cada corrida.
// Este nodo deja pasar todo igual, anota el token nuevo y cierra los de corridas anteriores de este mismo login
// (más de 30 min: ninguna corrida dura tanto). En reposo queda como mucho una sesión abierta por login.
const BASE = (() => { try { return String("https://apigrowth.mdarthurdigital.com").replace(/\/+$/, ''); } catch (e) { return ''; } })();
const st = $getWorkflowStaticData('global');
const k = 'sesionesG54__' + "\ud83d\udd10 G54: Login (Reply TG)";
const ahora = Date.now();
const quedan = [];
for (const s of (Array.isArray(st[k]) ? st[k] : [])) {
  if (ahora - s.t > 30 * 60e3) {
    try { await __httpConTope({ method: 'POST', url: s.b + '/api/auth/logout', headers: { Authorization: 'Bearer ' + s.tok, Accept: 'application/json' }, json: true, timeout: 5000 }); } catch (e) {}
  } else quedan.push(s);
}
const tok = $input.item.json && $input.item.json.access_token;
if (tok && BASE) quedan.push({ tok, b: BASE, t: ahora });
st[k] = quedan.slice(-50);
return $input.item;
